def clean_text(raw_text: str | None) -> str:
    if raw_text is None:
        return ""
    return raw_text.strip()

def fetch_user_id(data: dict[str, int]) -> int:
    val = data.get("user_id")
    if val is None:
        raise KeyError("user_id missing")
    return val

